ee:message.ee:set-payload:
%dw 2.0
output application/json
var fechaHoraColombia = (now() >> "America/Bogota") as String {
	format: "YYYY-MM-dd HH:mm:ss"
}
---
{
	basePath: p("mongo-db-sapi.base-path"),
	host: p("mongo-db-sapi.host"),
	port: p("mongo-db-sapi.port"),
	method: "POST",
	path: p('mongo-db-sapi.resources.dynamicQuery.base-path'),
	body: {
		"query": {
			"insert": "PAGOS_AUDITORIA",
			"documents": [{
				transactionId: vars.initialPayload.transactionId default "",
				origin: vars.initialPayload.origin default "",
				accountNumber: vars.initialPayload.accountNumber default "",
				payAmount: vars.initialPayload.payAmount default "",
				currencyCode: vars.initialPayload.currencyCode default "",
				channelCode: vars.initialPayload.channelCode default "",
				paymentMethodCode: vars.initialPayload.paymentMethodCode default "",
				bankAccountNumber: vars.initialPayload.bankAccountNumber default "",
				bankCode: vars.initialPayload.bankCode default "",
				paymentDate: vars.initialPayload.paymentDate default "",
				partyType: vars.initialPayload.partyType default "",
				partyCode: vars.initialPayload.partyCode default "",
				paymentParamList: vars.initialPayload.paymentParamList default {},
				source: "BANCO",
				processingDate: fechaHoraColombia,
				zsmartStatus: null,
				zsmartErrorCode: null

			}]
		}
	},
	headers: vars.queryHeaders default {
	},
	queryParameters: {
	},
	uriParameters: {
	}
}

%dw 2.0
output application/json skipNullOn = "everywhere"
var requestBody = vars.initialPayload - "username" - "password" - "origin"
---
{
	basePath: p("zsmart-sapi.base-path"),
	host: p("zsmart-sapi.host"),
	port: p("zsmart-sapi.port"),
	method: "POST",
	path: p('zsmart-sapi.resources.postPayment.path'),
	body: requestBody,
	headers: vars.queryHeaders default {
	},
	queryParameters: {
	},
	uriParameters: {
	}
}

%dw 2.0
output application/json
---
{
	basePath: p("mongo-db-sapi.base-path"),
	host: p("mongo-db-sapi.host"),
	port: p("mongo-db-sapi.port"),
	method: "POST",
	path: p('mongo-db-sapi.resources.dynamicQuery.base-path'),
	body: {
		"query": {
			"aggregate": "PAGOS_AUDITORIA",
			"pipeline": [{
				"\$match": {
					transactionId: vars.initialPayload.transactionId default null
				}
			}],
			"cursor": {
			}
		}
	},
	headers: vars.queryHeaders default {
	},
	queryParameters: {
	},
	uriParameters: {
	}
}

%dw 2.0
output application/json
---
{
	basePath: p("mongo-db-sapi.base-path"),
	host: p("mongo-db-sapi.host"),
	port: p("mongo-db-sapi.port"),
	method: "POST",
	path: p('mongo-db-sapi.resources.dynamicQuery.base-path'),
	body: {
		"query": {
			"update": "PAGOS_AUDITORIA",
			"updates": [{
				"q": {
					"_id": {
						"\$oid": vars.queryResponse.result[0]."_id"."\$oid"
					}
				},
				"u": {
					"\$set": vars.zsmartResponse default {}
				},
				"upsert": true,
				"multi": false
			}]
		}
	}, 
	headers: vars.queryHeaders default {
	},
	queryParameters: {
	},
	uriParameters: {
	}
}
